using System;using System.Drawing;using System.Windows.Forms;using Microsoft.Win32;using System.Runtime.InteropServices;using System.Collections.Generic;
namespace ContourWatch {
public static class AgentTheme {
 static string fallback="system";
 public static string Preference {get{try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\ContourWatch"))return k==null?fallback:Convert.ToString(k.GetValue("Theme",fallback));}catch(System.Security.SecurityException){return fallback;}catch(UnauthorizedAccessException){return fallback;}}}
 public static bool Dark {get{if(Preference!="system")return Preference=="dark";try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"))return k!=null&&Convert.ToInt32(k.GetValue("AppsUseLightTheme",1))==0;}catch(System.Security.SecurityException){return false;}catch(UnauthorizedAccessException){return false;}}}
 public static void Save(string theme){if(theme!="light"&&theme!="dark"&&theme!="system")throw new ArgumentException("theme");fallback=theme;try{using(var k=Registry.CurrentUser.CreateSubKey(@"Software\ContourWatch"))k.SetValue("Theme",theme);}catch(System.Security.SecurityException){}catch(UnauthorizedAccessException){}}
 public static Color Surface{get{return Dark?Color.FromArgb(18,28,30):Color.FromArgb(246,249,247);}}
 public static Color Field{get{return Dark?Color.FromArgb(31,45,47):Color.White;}}
 public static Color Ink{get{return Dark?Color.FromArgb(232,240,236):Color.FromArgb(27,48,41);}}
 [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
 [DllImport("uxtheme.dll",CharSet=CharSet.Unicode)]static extern int SetWindowTheme(IntPtr window,string application,string subId);
 static readonly HashSet<Control> Hooked=new HashSet<Control>();
 static void Native(Control c){if(!c.IsHandleCreated)return;try{if(c is Form){int dark=Dark?1:0;DwmSetWindowAttribute(c.Handle,20,ref dark,4);int color=ColorTranslator.ToWin32(Surface);DwmSetWindowAttribute(c.Handle,35,ref color,4);int ink=ColorTranslator.ToWin32(Ink);DwmSetWindowAttribute(c.Handle,36,ref ink,4);}else SetWindowTheme(c.Handle,Dark?"DarkMode_Explorer":"Explorer",null);}catch(DllNotFoundException){}catch(EntryPointNotFoundException){}}
 public static void Apply(Control root){Paint(root,Dark);}
 static void Paint(Control c,bool dark){var edit=c as TextBoxBase;if(edit!=null&&edit.BorderStyle!=BorderStyle.None)edit.BorderStyle=BorderStyle.FixedSingle;var list=c as ListBox;if(list!=null)list.BorderStyle=BorderStyle.FixedSingle;c.BackColor=dark?Color.FromArgb(18,28,30):Color.FromArgb(246,249,247);c.ForeColor=dark?Color.FromArgb(232,240,236):Color.FromArgb(27,48,41);if(c is TextBoxBase||c is ComboBox||c is ListBox)c.BackColor=dark?Color.FromArgb(31,45,47):Color.White;var button=c as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=dark?Color.FromArgb(61,80,77):Color.FromArgb(186,204,193);button.FlatAppearance.MouseOverBackColor=dark?Color.FromArgb(43,70,62):Color.FromArgb(217,238,226);}var check=c as CheckBox;if(check!=null)check.FlatStyle=FlatStyle.Flat;if(Hooked.Add(c)){c.HandleCreated+=(s,e)=>Native(c);c.Disposed+=(s,e)=>Hooked.Remove(c);}Native(c);foreach(Control child in c.Controls)Paint(child,dark);c.Invalidate();}
 public static ComboBox Picker(Control target){var picker=new ThemeCombo{DropDownStyle=ComboBoxStyle.DropDownList,Width=210};picker.Items.AddRange(new object[]{"Тема системы","Светлая тема","Тёмная тема"});picker.SelectedIndex=Preference=="dark"?2:Preference=="light"?1:0;picker.SelectedIndexChanged+=(s,e)=>{Save(picker.SelectedIndex==2?"dark":picker.SelectedIndex==1?"light":"system");foreach(Form form in Application.OpenForms)Apply(form);Apply(target);};return picker;}
 public static DialogResult ShowMessage(string text){return ShowMessage(null,text,"Контур",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 public static DialogResult ShowMessage(string text,string title){return ShowMessage(null,text,title,MessageBoxButtons.OK,MessageBoxIcon.Information);}
 public static DialogResult ShowMessage(string text,string title,MessageBoxButtons buttons,MessageBoxIcon icon){return ShowMessage(null,text,title,buttons,icon);}
 public static DialogResult ShowMessage(IWin32Window owner,string text,string title,MessageBoxButtons buttons,MessageBoxIcon icon){using(var form=new Form{Text=title,Width=650,Height=270,StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10),MinimizeBox=false,MaximizeBox=false,Padding=new Padding(16)}){var body=new TextBox{Text=text,ReadOnly=true,Multiline=true,WordWrap=true,BorderStyle=BorderStyle.None,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical};var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=45,FlowDirection=FlowDirection.RightToLeft};var ok=new Button{Text=buttons==MessageBoxButtons.OKCancel?"Подтвердить":"OK",AutoSize=true,DialogResult=DialogResult.OK};footer.Controls.Add(ok);if(buttons==MessageBoxButtons.OKCancel){var cancel=new Button{Text="Отмена",AutoSize=true,DialogResult=DialogResult.Cancel};footer.Controls.Add(cancel);form.CancelButton=cancel;}form.Controls.Add(body);form.Controls.Add(footer);form.AcceptButton=ok;Apply(form);return form.ShowDialog(owner);}}
 public static void Menu(ContextMenuStrip menu){PaintMenu(menu);}
 static void PaintMenu(ToolStrip strip){strip.BackColor=Dark?Color.FromArgb(24,36,38):Color.White;strip.ForeColor=Ink;strip.Renderer=new ToolStripProfessionalRenderer(new Palette());foreach(ToolStripItem item in strip.Items){item.BackColor=strip.BackColor;item.ForeColor=Ink;var nested=item as ToolStripDropDownItem;if(nested!=null&&nested.HasDropDownItems)PaintMenu(nested.DropDown);}}
 class Palette:ProfessionalColorTable{public override Color MenuBorder{get{return Dark?Color.FromArgb(61,80,77):Color.FromArgb(186,204,193);}}public override Color ToolStripBorder{get{return MenuBorder;}}public override Color MenuItemSelectedGradientBegin{get{return MenuItemSelected;}}public override Color MenuItemSelectedGradientEnd{get{return MenuItemSelected;}}public override Color MenuItemPressedGradientBegin{get{return MenuItemSelected;}}public override Color MenuItemPressedGradientMiddle{get{return MenuItemSelected;}}public override Color MenuItemPressedGradientEnd{get{return MenuItemSelected;}}public override Color MenuItemSelected{get{return Dark?Color.FromArgb(43,70,62):Color.FromArgb(217,238,226);}}public override Color MenuItemBorder{get{return MenuItemSelected;}}public override Color ToolStripDropDownBackground{get{return Dark?Color.FromArgb(24,36,38):Color.White;}}public override Color ImageMarginGradientBegin{get{return ToolStripDropDownBackground;}}public override Color ImageMarginGradientMiddle{get{return ToolStripDropDownBackground;}}public override Color ImageMarginGradientEnd{get{return ToolStripDropDownBackground;}}}
 class ThemeCombo:ComboBox{public ThemeCombo(){DrawMode=DrawMode.OwnerDrawFixed;FlatStyle=FlatStyle.Flat;}protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(selected?(Dark?Color.FromArgb(43,70,62):Color.FromArgb(217,238,226)):Field))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,Convert.ToString(Items[e.Index]),Font,e.Bounds,Ink,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);e.DrawFocusRectangle();}protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==15&&IsHandleCreated){using(var g=Graphics.FromHwnd(Handle)){using(var border=new Pen(Dark?Color.FromArgb(61,80,77):Color.FromArgb(186,204,193)))g.DrawRectangle(border,0,0,Width-1,Height-1);var r=new Rectangle(Width-22,1,21,Height-2);using(var brush=new SolidBrush(Field))g.FillRectangle(brush,r);using(var pen=new Pen(Ink,1.5f)){int x=r.Left+r.Width/2,y=r.Top+r.Height/2;g.DrawLines(pen,new[]{new Point(x-4,y-2),new Point(x,y+2),new Point(x+4,y-2)});}}}}}
 public class AgentCheckBox:CheckBox{public AgentCheckBox(){SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);}protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);int size=Math.Max(12,(int)(14*e.Graphics.DpiX/96)),top=(Height-size)/2;var box=new Rectangle(Padding.Left,top,size,size);using(var brush=new SolidBrush(Field))e.Graphics.FillRectangle(brush,box);using(var border=new Pen(Dark?Color.FromArgb(93,120,113):Color.FromArgb(115,140,128)))e.Graphics.DrawRectangle(border,box);if(Checked)using(var pen=new Pen(Dark?Color.FromArgb(112,223,192):Color.FromArgb(22,116,93),2))e.Graphics.DrawLines(pen,new[]{new Point(box.Left+3,box.Top+size/2),new Point(box.Left+size/2-1,box.Bottom-3),new Point(box.Right-2,box.Top+3)});var text=new Rectangle(box.Right+6,0,Math.Max(0,Width-box.Right-6),Height);TextRenderer.DrawText(e.Graphics,Text,Font,text,ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(e.Graphics,text,ForeColor,BackColor);}}
}
}
